<script setup lang="ts">
import {useCatalogPage} from '../../stores/useCatalogPage';
const {prefs,products,categories,pending,failed,query,category,shown,categoryName,reload,open,back,mobilePreferenceStyle,formatAmount,mobileProductName,mobileProductPicture} = useCatalogPage();
</script>
<template><view class="app-page catalog-page" :class="{'kx-care':prefs.care,'kx-dark':prefs.theme==='dark','kx-system':prefs.theme==='system','kx-reduce-motion':prefs.reduceMotion}" :style="mobilePreferenceStyle(prefs)">
  <view class="catalog-header"><text class="back-link" @click="back">‹ {{$t('m2.mobile.back')}}</text><text class="catalog-kicker">{{$t('m2.catalog.kicker')}}</text><text class="page-heading">{{$t('m2.mobile.homeCatalog')}}</text><text class="subline">{{$t('m2.catalog.recentLimit')}}</text></view>
  <view class="catalog-search"><input v-model="query" :placeholder="$t('m2.catalog.search')" confirm-type="search"/><text v-if="query" @click="query=''">×</text></view>
  <scroll-view scroll-x class="category-scroll"><view class="category-row"><view class="category-pill" :class="{chosen:category===null}" @click="category=null">{{$t('m2.catalog.all')}}</view><view v-for="c in categories" :key="String(c.id)" class="category-pill" :class="{chosen:category===String(c.id)}" @click="category=String(c.id)">{{categoryName(c)}}</view></view></scroll-view>
  <view class="catalog-summary row-between"><text>{{$t('m2.catalog.count',{count:shown.length})}}</text><text class="refresh-link" @click="reload">{{$t('m2.catalog.retry')}}</text></view>
  <view v-if="pending" class="empty-box">{{$t('m2.catalog.loading')}}</view>
  <view v-else-if="failed" class="error-box">{{$t('m2.catalog.failed')}}<button class="secondary-btn" @click="reload">{{$t('m2.catalog.retry')}}</button></view>
  <view v-else-if="!shown.length" class="empty-box">{{$t(products.length?'m2.catalog.noResults':'m2.catalog.noData')}}</view>
  <view v-else class="catalog-grid"><view v-for="p in shown" :key="p.id" class="catalog-item" @click="open(p)"><view class="catalog-image"><image v-if="mobileProductPicture(p)" :src="mobileProductPicture(p)" mode="aspectFill"/><text v-else class="catalog-placeholder">✦</text></view><view class="catalog-card-body"><text class="catalog-region">{{p.region||$t('m2.catalog.originUnknown')}}</text><text class="catalog-product-name">{{mobileProductName(p)}}</text><text class="catalog-price">{{formatAmount(p.price,p.currency)}}</text></view></view></view>
</view></template>
