.catalog-page{padding-top:32rpx}.catalog-header{display:flex;flex-direction:column;gap:8rpx}.back-link{font-size:25rpx;color:var(--kx-primary);padding:15rpx 0}.catalog-kicker{font-size:20rpx;font-weight:800;color:#64748b;letter-spacing:4rpx}.page-heading{font-size:43rpx;margin:10rpx 0}.catalog-search{margin:28rpx 0 20rpx;border:1rpx solid var(--kx-border);border-radius:16rpx;padding:10rpx 24rpx;display:flex;align-items:center;background:white}.catalog-search input{flex:1;height:70rpx;font-size:27rpx}.catalog-search text{padding:15rpx}.category-scroll{width:100%;white-space:nowrap}.category-row{display:flex;align-items:center;gap:14rpx;padding:4rpx 0 18rpx}.category-pill{background:#fff;border:1rpx solid #e2e8f0;border-radius:28rpx;padding:13rpx 21rpx;font-size:24rpx;color:#475569;flex-shrink:0;white-space:normal;max-width:320rpx}.category-pill.chosen{background:#0ea5e9;color:white}.catalog-summary{color:#64748b;font-size:23rpx;margin:22rpx 0}.refresh-link{color:#0284c7}.catalog-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18rpx}.catalog-item{border-radius:19rpx;background:white;border:1rpx solid var(--kx-border);overflow:hidden;min-width:0}.catalog-image{height:270rpx;background:#e8efe7;display:grid;place-items:center;overflow:hidden}.catalog-image image{width:100%;height:100%}.catalog-placeholder{color:#a1baaa;font-size:70rpx}.catalog-card-body{padding:18rpx;display:flex;flex-direction:column;gap:10rpx}.catalog-region{font-size:21rpx;color:#81968a}.catalog-product-name{font-size:26rpx;font-weight:700;line-height:1.5;color:#335943;min-height:80rpx;overflow-wrap:anywhere}.catalog-price{font-size:28rpx;color:var(--kx-primary);font-weight:800}.error-box .secondary-btn{margin-top:15rpx}@media screen and (min-width:768px){.catalog-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
